rule.definition:
a!localVariables(
  local!isOldVersion: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn) < #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false
    )
  ),

  if(
  or(
    ri!taskStatus = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4558858",
    ri!taskStatus = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4571294",
    ri!taskStatus = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4570051",
    ri!taskStatus = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489843",
    ri!taskStatus = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489857",
    ri!taskStatus = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4576069",
    ri!taskStatus = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4570066",
    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(ri!nomination, "nominationId",tointeger(null)))
  ),
  and(

    if(
      toboolean(local!isOldVersion)=true,
      if(
        not(isnull(ri!nomination.isOpsAdditionalVettingReq)),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.vettingComments),
      true
    ),
    if(
     ri!nomination.isOpsAdditionalVettingReq=true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.vettingComments),
      true
    )),
    if(
      or(
        index(ri!nomination, "isAdditionalFollowUpReq", null)=true,
        index(ri!nomination, "isReapprovedByBU", null)=true
      ),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.operationsComments),
      true
    ),
    or(
      ri!nomination.isReapprovedByBU = true,
      ri!nomination.isOpsAdditionalVettingReq = true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isInspectionsReview),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isHRReview)
    )
  ),
  true
)
)
